Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

#[local] Abbreviation ASEGS := AsanUbsan.M.loaded_segments.
#[local] Abbreviation cellA := (cell AsanUbsan.M.loaded_segments).
#[local] Abbreviation wrA := (wr AsanUbsan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

Definition SB : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,0|N3fff8000;").
Definition kHighMemEnd : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,0|^13fffffffffff;").
Definition kHighMemBeg : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,0|\0007fff8000;").   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition art_layout (M : word -> option byte) : Prop :=
  cellA M 0x164518 8 0x16d7b8 /\ cellA M 0x16d7b8 8 SB               (* [comment removed for export] *)
  /\ cellA M 0x164520 8 0x16e4a8 /\ cellA M 0x16e4a8 8 0             (* [comment removed for export] *)
  /\ cellA M 0x164528 8 0x16e4b0 /\ cellA M 0x16e4b0 8 0             (* [comment removed for export] *)
  /\ cellA M 0x164530 8 0x16e4a0 /\ cellA M 0x16e4a0 8 kHighMemEnd   (* [comment removed for export] *)
  /\ cellA M 0x164510 8 0x16afb8 /\ cellA M (0x16afb8 + 78) 1 1      (* [comment removed for export] *)
  /\ cellA M 0x164538 8 0x166550 /\ cellA M 0x166550 8 0x1568bc       (* [comment removed for export] *)
  /\ cellA M 0x164508 8 0x1ff2e8 /\ cellA M (0x1ff2e8 + 120) 8 18446744073709551615  (* [comment removed for export] *)
  /\ cellA M 0x16d01c 1 1.                                         (* [comment removed for export] *)

Lemma art_layout_Wn : forall n M a v, 0 <= a -> a + Z.of_nat n < 2 ^ 64 ->
